// dsh-local-kit - merged host half (generated by build-local-kit.mjs).
// Applies the four local plugins' host halves in one cordis plugin row.
import * as dsmon from "./features/dsmon/lib/index.js";
import * as message_preview from "./features/message-preview/lib/index.js";
import * as drag_and_drop from "./features/drag-and-drop/lib/index.js";
import * as file_mentions from "./features/file-mentions/lib/index.js";

export const name = "dsh-local-kit";
export const inject = ["webServer", "sessions"];

const FEATURES = [dsmon, message_preview, drag_and_drop, file_mentions];

export function apply(ctx, config) {
  for (const feature of FEATURES) {
    if (typeof feature.apply === "function") feature.apply(ctx, config);
  }
}
